def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None


def installed_source():
    try:
        dist = importlib.metadata.distribution("vllm-ascend")
    except importlib.metadata.PackageNotFoundError as exc:
        raise SystemExit("Cannot locate editable VA. Pass --source /absolute/path/to/VA.") from exc
    direct = json.loads(dist.read_text("direct_url.json") or "{}")
    if direct.get("dir_info", {}).get("editable") and direct.get("url", "").startswith("file:"):
        return pathlib.Path(unquote(urlparse(direct["url"]).path))
    raise SystemExit("Cannot locate editable VA. Pass --source /absolute/path/to/VA.")


def check_paths(root):
    for name in AFTER:
        path = root / name
        relative = pathlib.PurePosixPath(name)
        if relative.is_absolute() or ".." in relative.parts:
            raise SystemExit("Invalid embedded target path: " + name)
        for entry in (path, *path.parents):
            if entry == root:
                break
            if entry.is_symlink():
                raise SystemExit("Refusing symlink target or ancestor: " + name + "; no files changed.")
        if not path.resolve().is_relative_to(root):
            raise SystemExit("Refusing target outside source: " + name + "; no files changed.")
        if path.exists() and not path.is_file():
            raise SystemExit("Refusing non-file target: " + name + "; no files changed.")


def state(root):
    check_paths(root)
    return {name: digest(root / name) for name in AFTER}


def git(root, *args, **kwargs):
    return subprocess.run(["git", "--no-optional-locks", "-C", str(root), *args], check=True, **kwargs)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=pathlib.Path, help="Pinned editable VA source checkout.")
    parser.add_argument("--check", action="store_true", help="Read-only preflight; no backup or file changes.")
    args = parser.parse_args()
    root = (args.source or installed_source()).resolve()
    if not (root / "vllm_ascend/ascend_config.py").is_file():
        raise SystemExit("Not a VA source directory: " + str(root))
    top = pathlib.Path(git(root, "rev-parse", "--show-toplevel", capture_output=True, text=True).stdout.strip()).resolve()
    if top != root:
        raise SystemExit("--source must be the repository root; no files changed.")
    head = git(root, "rev-parse", "HEAD", capture_output=True, text=True).stdout.strip()
    if head != BASE:
        raise SystemExit("Base mismatch: expected " + BASE + ", got " + head + "; no files changed.")
    actual = state(root)
    if actual == AFTER:
        print("QFM_VA030_ONLY_ALREADY_APPLIED source=" + str(root))
        return
    mode = next((key for key, expected in KNOWN_STATES.items() if actual == expected), None)
    if mode is None:
        unknown = [name for name in AFTER if actual[name] not in
                   [AFTER[name], *(known[name] for known in KNOWN_STATES.values())]]
        detail = "\nUnknown file hashes:\n" + "\n".join(unknown) if unknown else "\nFiles match different known states."
        raise SystemExit("Unknown or mixed patch state; no files changed. Existing backups are retained. Do not force/reset." + detail)
    payload = PATCHES[mode]
    patch = gzip.decompress(base64.b64decode(payload["data"], validate=True))
    if hashlib.sha256(patch).hexdigest() != payload["sha256"]:
        raise SystemExit("Embedded patch checksum failed; no files changed.")
    git(root, "apply", "--check", "-", input=patch)
    removed = [name for name, old_hash in actual.items() if old_hash is not None and AFTER[name] is None]
    restored = [name for name in RESTORED_BASE_PATHS if actual[name] != AFTER[name]]
    if args.check:
        print("QFM_VA030_ONLY_PREFLIGHT_OK mode=" + mode + " source=" + str(root))
        print("REMOVE=" + str(len(removed)) + " RESTORE_BASE=" + str(len(restored)))
        return
    backup = pathlib.Path(tempfile.mkdtemp(prefix="va030-qfm-only-backup-"))
    print("BACKUP=" + str(backup), flush=True)
    for name, old_hash in actual.items():
        if old_hash is not None:
            dest = backup / name
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(root / name, dest)
            if digest(dest) != old_hash:
                raise SystemExit("Source changed during backup. No patch applied; inspect backup=" + str(backup))
    manifest = {
        "source": str(root), "base": BASE, "mode": mode,
        "before": actual, "after": AFTER, "patch_sha256": payload["sha256"],
        "removed_files": removed, "restored_base_files": restored,
    }
    (backup / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    if state(root) != actual:
        raise SystemExit("Source changed during preflight. No patch applied; inspect backup=" + str(backup))
    try:
        git(root, "apply", "-", input=patch)
        if state(root) != AFTER:
            raise RuntimeError("Post-apply target hash mismatch")
        for name, target_hash in AFTER.items():
            if target_hash is not None and name.endswith(".py"):
                compile((root / name).read_text(encoding="utf-8"), name, "exec")
    except Exception as exc:
        raise SystemExit("Installation failed; stop and inspect. Backup retained at " + str(backup) + ": " + str(exc)) from exc
    print("QFM-only candidate: full576 FP8 Cache and QFM Attention; removed FIA/QFA/paged experiment modules and restored their upstream-only hooks.")
    print("Removed experimental files=" + str(len(removed)) + "; restored baseline files=" + str(len(restored)))
    print("Use enable_kimi_k3_qfm_c8=true, enable_kv_nz=false and --kv-cache-dtype auto; block-size must remain a positive multiple of128.")
    print("Existing QFM/metadata and optional DSL Prolog dependencies must be loaded separately in every new Worker environment.")
    print("RESTART ALL WORKERS and discard old in-memory KV/APC pages. No packages installed, no native operators rebuilt, no NPU/model tests run automatically.")
    print("QFM_VA030_ONLY_APPLIED mode=" + mode + " source=" + str(root))


if __name__ == "__main__":
    main()
